using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Repositories.Interfaces;using JamunaBank.Procurement.API.Services.Interfaces;
namespace JamunaBank.Procurement.API.Services.Implementations;
public sealed class ManagerWorkflowService(IManagerWorkflowRepository repository,ICurrentUserService currentUser):IManagerWorkflowService
{
 public Task<IReadOnlyList<ManagerPendingRequisitionDto>>GetPendingAsync(CancellationToken ct)=>repository.GetPendingAsync(currentUser.EmployeeId,ct);public Task<RequisitionDetailDto?>GetDetailAsync(long id,CancellationToken ct){Positive(id);return repository.GetDetailAsync(id,currentUser.EmployeeId,ct);}public Task<StoredProcedureResult?>ApproveAsync(long id,string?remarks,CancellationToken ct){Positive(id);Length(remarks);return repository.ApproveAsync(id,currentUser.EmployeeId,remarks,ct);}public Task<StoredProcedureResult?>ReturnAsync(long id,string?remarks,CancellationToken ct){Positive(id);var m=Required(remarks);return repository.ReturnAsync(id,currentUser.EmployeeId,m,ct);}public Task<StoredProcedureResult?>RejectAsync(long id,string?remarks,CancellationToken ct){Positive(id);var m=Required(remarks);return repository.RejectAsync(id,currentUser.EmployeeId,m,ct);}private static string Required(string?m){if(string.IsNullOrWhiteSpace(m))throw new ArgumentException("Remarks are required for return and reject.");Length(m);return m.Trim();}private static void Length(string?m){if(m?.Length>2000)throw new ArgumentException("Remarks cannot exceed 2000 characters.");}private static void Positive(long id){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));}
}
